---模型加载接口，非GameObject不要做实例化
function NewChapterShared:LoadModelAsync(path)
    if self._loadedRes == nil then
        self._loadedRes = {}
    end

    local modelLoader = ResourceModule.LoadBundleAsync(path, function(loader, isOk, resultObject)
        if isOk then
            if not isNull(self._loadedRes) then
                if resultObject:GetType() == typeof(GameObject) then
                    local modelIns = GameObject.Instantiate(resultObject)
                    KTool.SetActive(modelIns.gameObject, false)
                    self._loadedRes[path] = {
                        go = modelIns,
                        loader = loader
                    }
                else
                    self._loadedRes[path] = {
                        go = resultObject,
                        loader = loader
                    }
                end
            else
                loader:Release()
            end
        else
            self._loadedRes[path] = false
            loader:Release()
        end
    end)

    return modelLoader
end 

---之后不要调用这个方法，请使用LoadModelAsync
function NewChapterShared:LoadModel(path, mode, callback)
    if self._loadedRes == nil then
        self._loadedRes = {}
    end

    if isSet(self._loadedRes, path) then
        if callback ~= nil then
            callback(self._loadedRes[path])
        end
        return false
    end

    if isSet(self._loadCo, path) then
        return true
    end

    if mode == nil then
        mode = 1
    end
    
    local yieldFunc = cs_coroutine.start(function()
        --printInfo("LoadModel")
        if mode == 1 then
            coroutine.yield(Yielders.EndOfFrame)
        end

        local modelLoader = nil
        if mode == 1 then
            modelLoader = ResourceModule.LoadBundleAsync(path, nil, true)
            while not modelLoader.IsCompleted do
                coroutine.yield(Yielders.EndOfFrame)
            end
        else
            modelLoader = ResourceModule.LoadBundleSync(path, nil, true)
        end
        if self._loadedRes == nil then
            self._loadedRes = {}
        end
        if modelLoader.IsSuccess then
             local modelIns = GameObject.Instantiate(modelLoader.ResultObject)
            --local modelIns = modelLoader:Instantiate()
            KTool.SetActive(modelIns.gameObject, false)
            self._loadedRes[path] = {
                go = modelIns,
                loader = modelLoader
            }
            --modelLoader:Release()
        else
            self._loadedRes[path] = false
            modelLoader:Release()
        end
        printInfo("loader refcount " .. tostring(modelLoader.RefCount))

        if isSet(self._loadCo, path) then
            self._loadCo[path] = nil
        end

        if callback ~= nil then
            callback(self._loadedRes[path])
        end

        --printInfo("_loadedRes")
        --print(table.dump(self._loadedRes))
    end)

    --local co = CoWait.Start():Coroutine(yieldFunc)
    if self._loadCo == nil then
        self._loadCo = {}
    end

    if mode == 1 then
        self._loadCo[path] = yieldFunc
    end

    return true
end

function NewChapterShared:GetModel(path)
    if isSet(self._loadedRes, path) then
        if type(self._loadedRes[path]) == 'boolean' then
            return nil
        end
        --printInfo(path)
        return self._loadedRes[path].go
    end
    return nil
end

function NewChapterShared:DisposeCo()

    if self._loadCo ~= nil then
        for k, v in pairs(self._loadCo) do
            --CS.CoroutineModule.Instance:StopCo(v)
            cs_coroutine.stop(v)
        end
        self._loadCo = nil
    end
end

function NewChapterShared:DisposeAllModel()
    if self._loadedRes ~= nil then
        for k, v in pairs(self._loadedRes) do
            if not isNull(v) and type(v) ~= 'boolean' then

                --printInfo(v.go:GetType())
                if v.go:GetType() == typeof(GameObject) then
                    local lip = v.go:GetComponent(typeof(CriLipsDeformerForAtomSource))
                    if not isNull(lip) and not isNull(lip.atomAnalyzer) then
                        lip.atomAnalyzer:Dispose()
                    end

                    GameObject.Destroy(v.go)
                end
                

                
                if not isNull(v.loader) then
                    v.loader:Release()
                end
            end
        end
        self._loadedRes = nil
    end
end

function NewChapterShared:GetOrCreateTrans(path, is2D, rootTrans)
    local object = rootTrans:Find(path)
    if isNull(object) then
        object = GameObject(path)
        object = object.transform
        object:SetParent(rootTrans)
        object.localPosition = Vector3.New()
        object.localScale = Vector3.New(1,1,1)

        if is2D then
            object.gameObject:EnsureComponent(typeof(DicedSpriteRenderer))
        else
            local mask = rootTrans:Find(NewChapterConstants.MaskPath)
            if not isNull(mask) then
                local ins = GameObject.Instantiate(mask)
                ins.name = NewChapterConstants.MaskPath
                local trans = ins.transform
                trans:SetParent(object)
                trans.localPosition = Vector3.New(0,1,0)
                trans.localScale = Vector3.New(1,1,1)
                KTool.SetActive(ins, false)
            end
        end
        
        object.gameObject.layer = rootTrans.gameObject.layer
    end
    
    return object
end

function NewChapterShared:LoadSprite(bgObject, path, callBack )
