function NewChapterShared:LoadDicedSprite(diceObject, path, name)
    if isNull(diceObject) then
        return
    end
    local render = diceObject.gameObject:GetComponent(typeof(DicedSpriteRenderer))
    if isNull(diceObject) then
        return
    end
    if isNull(render.DicedSprite) then
        render.enabled = false
    end

    self:LoadModel(path, 2)
    local atlas = self:GetModel(path)
    --printInfo(path)
    
    if isNull(atlas) then
        printInfo("load empty")
        return
    end
    
    render.DicedSprite = atlas:GetSprite(name);

    --printInfo(name)
    if not isNull(render.DicedSprite) then
        render.enabled = true
    else
        printError("%s %s not found", path, name)
    end
end

