---@return BaseEffect, number @EffectScript, NewChapterConstants.ScreenEffectType
function NewChapterShared:GetScreenEffect(type)
    if self._cachedEffects == nil then
        self._cachedEffects = {}
    end
    local script, isImage = self:GetScreenName(type)
    if script == nil or isImage == nil then
        return
    end
    printInfo("GetScreenEffect %s", script)
    if not isSet(self._cachedEffects, script) then
        local lua = import(string.format(NewChapterConstants.ScreenEffectScript, script))
        self._cachedEffects[script] = lua:New()
    end
    script = self._cachedEffects[script]
    return script, isImage
    
end

---@return BaseEffect, boolean @EffectScript, needCamera
function NewChapterShared:GetCharacterEffect(type)
    if self._cachedEffects == nil then
        self._cachedEffects = {}
    end
    local script, needCamera = self:GetCharacterName(type)
    if script == nil or needCamera == nil then
        return
    end
    printInfo("GetCharacterEffect %s", script)
    local name = table.concat({script,"_",type})
    if not isSet(self._cachedEffects, name) then
        local lua = import(string.format(NewChapterConstants.ScreenEffectScript, script))
        self._cachedEffects[name] = lua:New()
    end

    script = self._cachedEffects[name]
    return script, needCamera
end

---@return string,number @scriptName, NewChapterConstants.ScreenEffectType
function NewChapterShared:GetScreenName(type)
    if type >= NewChapterConstants.ScreenEffect.BlackFadeIn and type <= NewChapterConstants.ScreenEffect.RedFadeIn then
        return "FadeInScreenEffect", NewChapterConstants.ScreenEffectType.Image
    elseif type >= NewChapterConstants.ScreenEffect.Black and type <= NewChapterConstants.ScreenEffect.Red then
        return "ScreenColorEffect", NewChapterConstants.ScreenEffectType.Image
    elseif type == NewChapterConstants.ScreenEffect.KeepShake then
        return "ScreenShakeEffect", NewChapterConstants.ScreenEffectType.Bg
    elseif type == NewChapterConstants.ScreenEffect.LookAround then
        return "ScreenLookAroundEffect", NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type == NewChapterConstants.ScreenEffect.Attack then
        return "ScreenAttackEffect", NewChapterConstants.ScreenEffectType.Image
    elseif type == NewChapterConstants.ScreenEffect.Memory then
        return "ScreenMemoryEffect", NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type == NewChapterConstants.ScreenEffect.Rain then
        return "ScreenRainEffect", NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type == NewChapterConstants.ScreenEffect.Fire then
        return "ScreenFireEffect", NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type == NewChapterConstants.ScreenEffect.ScreenBreak then
        return "ScreenBreakingEffect", NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type == NewChapterConstants.ScreenEffect.ScreenBlackFog or type == NewChapterConstants.ScreenEffect.ScreenWhiteFog then
        return "ScreenFogEffect", NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type == NewChapterConstants.ScreenEffect.WhiteShining then
        return "ScreenShineEffect", NewChapterConstants.ScreenEffectType.Image
    elseif type == NewChapterConstants.ScreenEffect.FullBlackFadeIn or type == NewChapterConstants.ScreenEffect.FullBlackFadeOut then
        return "ScreenTurningEffect", NewChapterConstants.ScreenEffectType.FullBlock
    elseif type == NewChapterConstants.ScreenEffect.CgBlackFadeIn or type == NewChapterConstants.ScreenEffect.CgBlackFadeOut then
        return "ScreenTurningEffect", NewChapterConstants.ScreenEffectType.Image
    elseif type == NewChapterConstants.ScreenEffect.SmallDebris or type == NewChapterConstants.ScreenEffect.BigDebris then
        return "ScreenDebrisEffect", NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type == NewChapterConstants.ScreenEffect.Comic then
        return "ScreenComicEffect", NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type == NewChapterConstants.ScreenEffect.KeepShakeLong then
        return "ScreenShakeLongEffect", NewChapterConstants.ScreenEffectType.Bg
    elseif type == NewChapterConstants.ScreenEffect.KeepShakeWave then
        return "ScreenShakeWaveEffect", NewChapterConstants.ScreenEffectType.Bg
    elseif type == NewChapterConstants.ScreenEffect.SpeedLine then
        return "ScreenSpeedLineEffect", NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type == NewChapterConstants.ScreenEffect.SceneWarning then
        return "SceneWarningEffect" , NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type == NewChapterConstants.ScreenEffect.SceneOldMovie then
        return "SceneOldMovieEffect" , NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type == NewChapterConstants.ScreenEffect.WhiteFadeOut then
        return "FadeInScreenEffect", NewChapterConstants.ScreenEffectType.Image
    elseif type == NewChapterConstants.ScreenEffect.SceneEmotional then
        return "SceneEmotionalEffect" , NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type == NewChapterConstants.ScreenEffect.SceneFire then
        return "SceneFireEffect" , NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type == NewChapterConstants.ScreenEffect.CameraShake   then
        return "SceneCameraShakeEffect" , NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type > NewChapterConstants.ScreenEffect.SceneCameraStart and type <= NewChapterConstants.ScreenEffect.SceneCameraEnd then
        return "SceneCameraBaseEffect" , NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type == NewChapterConstants.ScreenEffect.SceneCameraBlue then
        return "SceneCameraBlueEffect" , NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type == NewChapterConstants.ScreenEffect.SceneBadSignal then
        return "SceneCameraBadSignal" , NewChapterConstants.ScreenEffectType.SceneCamera
    elseif type >= NewChapterConstants.ScreenEffect.SceneBgSuccess and type <= NewChapterConstants.ScreenEffect.SceneBgEnd then
        return "SceneBgPosEffect" , NewChapterConstants.ScreenEffectType.Bg
    end
end

---@return string,boolean @scriptName,needCamera
function NewChapterShared:GetCharacterName(type)
    if type == NewChapterConstants.CharacterEffect.Anonymous then
        return "CharacterAnonymousEffect", false
    elseif type == NewChapterConstants.CharacterEffect.PhoneCall then
        return "CharacterTeleportEffect", true
    elseif type == NewChapterConstants.CharacterEffect.Darken then
        return "CharacterDarkenEffect", false
    elseif type >= NewChapterConstants.CharacterEffect.EmotionalBlue and type <= NewChapterConstants.CharacterEffect.CharacterEffectEnd then
        return "CharacterNormalEffect", false
    elseif type == NewChapterConstants.CharacterEffect.ChapterDissolve then
        return "CharacterDissolveEffect", true
    elseif type == NewChapterConstants.CharacterEffect.ChapterChangeColor then
        return "ChapterChangeColorEffect", false
    end
end

